WITH sales AS ( SELECT cs.cs_ship_mode_sk, cs.cs_item_sk, td.t_shift, SUM(cs.cs_net_profit) AS total_sales_profit FROM catalog_sales cs JOIN time_dim td ON cs.cs_sold_time_sk = td.t_time_sk WHERE cs.cs_sold_date_sk IN (2450820, 2450821) GROUP BY cs.cs_ship_mode_sk, cs.cs_item_sk, td.t_shift ), sales_item AS ( SELECT s.cs_ship_mode_sk, s.cs_item_sk, i.i_category, s.t_shift, s.total_sales_profit FROM sales s JOIN item i ON s.cs_item_sk = i.i_item_sk ), returns AS ( SELECT sr.sr_item_sk, td.t_shift, SUM(sr.sr_net_loss) AS total_return_loss FROM store_returns sr JOIN time_dim td ON sr.sr_return_time_sk = td.t_time_sk WHERE sr.sr_returned_date_sk IN (2450820, 2450821) GROUP BY sr.sr_item_sk, td.t_shift ), returns_item AS ( SELECT r.sr_item_sk, i.i_category, r.t_shift, r.total_return_loss FROM returns r JOIN item i ON r.sr_item_sk = i.i_item_sk ) SELECT sm.sm_ship_mode_id, si.i_category, si.t_shift, si.total_sales_profit, COALESCE(ri.total_return_loss, 0) AS total_return_loss, si.total_sales_profit - COALESCE(ri.total_return_loss, 0) AS net_profit_after_returns, RANK() OVER (ORDER BY (si.total_sales_profit - COALESCE(ri.total_return_loss, 0)) DESC) AS profit_rank FROM sales_item si JOIN ship_mode sm ON si.cs_ship_mode_sk = sm.sm_ship_mode_sk LEFT JOIN returns_item ri ON si.cs_item_sk = ri.sr_item_sk AND si.t_shift = ri.t_shift AND si.i_category = ri.i_category WHERE si.total_sales_profit > 1000 ORDER BY net_profit_after_returns DESC LIMIT 20
